using System;using UnityEditor;using UnityEngine;using VisualAlgo.StartMenu;
public static class BuildHullMenuHover {
 public static string Run(){if(EditorApplication.isPlaying)throw new Exception("Stop playing");const string path="Assets/StartMenu/Prefabs/StartMenuPanel.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var panel=root.GetComponent<StartMenuPanel>();for(int i=3;i<5;i++){var button=panel.entries[i];var art=button.transform.Find("Algorithm symbol");var old=art.GetComponent<MenuGraphic>();Color accent=old?old.color:art.GetComponent<HullMenuPreview>().color;if(old)UnityEngine.Object.DestroyImmediate(old);var preview=art.GetComponent<HullMenuPreview>();if(!preview)preview=art.gameObject.AddComponent<HullMenuPreview>();preview.spatial=i==4;preview.movingPointColor=new Color(.85f,.08f,.48f);preview.color=accent;preview.raycastTarget=false;var hover=button.GetComponent<HullMenuHover>();if(!hover)hover=button.gameObject.AddComponent<HullMenuHover>();hover.preview=preview;}PrefabUtility.SaveAsPrefabAsset(root,path);return "Saved two animated hull button previews";}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
